suppressPackageStartupMessages({library(data.table);library(ggplot2);library(jsonlite);library(png);library(ggrastr)})
a<-commandArgs(TRUE);root<-normalizePath(a[1]);s<-a[2];out<-file.path(root,s);old<-file.path(dirname(root),'hd_major_annotation_v1');fig<-file.path(out,'figures');dir.create(fig,showWarnings=FALSE)
skill<-'/home/data/t070721/.agents/skills/jins-routine-plotting';for(f in c('theme','palettes','export'))source(file.path(skill,'common',paste0(f,'.R')));source(file.path(skill,'plot_types/UMAP_cluster/plot.R'));jin_setup()
colors<-c(Epithelial='#f5b264','T/NK'='#57c1b5',Myeloid='#80a2d3',Fibroblast='#ebdf5a',Endothelial='#ffc857',Mast='#00baee',B='#bbcf5c',Plasma='#82cfad',Mural='#b395c8',Unknown='#a8a8a8');d<-fread(file.path(out,'diagnosis.tsv.gz'),na.strings=c('','NA'));set.seed(123);options(jin.plotting.colors=colors)
export<-function(p,name,w=7,h=5.4,pw=5.4,raster=FALSE){if(file.exists(file.path(fig,paste0(name,'.png')))&&!startsWith(name,'ROI_'))return(invisible(NULL));if(raster)p$layers[[1]]<-ggrastr::rasterise(p$layers[[1]],dpi=300);jin_export(p,file.path(fig,name),w,h,panel_width=pw)}
for(route in c('blca','hpca')) {d[[paste0('candidate_',route)]]<-d[[paste0('singler_',route,'_pruned_labels')]];d[is.na(get(paste0('candidate_',route))),(paste0('candidate_',route)):='Unknown']}
# Same existing embedding, full denominator, fixed palette; candidates are not revised labels.
for(k in c('final_major','candidate_blca','candidate_hpca')){lev<-names(colors)[names(colors)%in%unique(d[[k]])];p<-plot_umap_cluster(d,'UMAP1','UMAP2',k,order=lev,colors=colors,legend_title=if(k=='final_major')'Original major' else 'Candidate',point_size=.13,label_size=0);export(p,paste0('umap_',k),raster=TRUE)}
stcol<-c(unknown='#aaaaaa',low_confidence='#df9f32',supported='#2878b5');z<-melt(d[,.(annotation_status,nFeature_RNA,nCount_RNA,n_bins)],id.vars='annotation_status');p<-ggplot(z,aes(annotation_status,log10(1+value),fill=annotation_status))+geom_boxplot(outlier.shape=NA,linewidth=.4,show.legend=FALSE)+facet_wrap(~variable,scales='free_y')+scale_fill_manual(values=stcol)+jin_theme()+theme(axis.text.x=element_text(angle=45,hjust=1))+labs(x=NULL,y='log10(1 + value)');export(p,'information_distributions',10,4.5,10)
z<-d[final_major=='Unknown',.(n=.N,UMI=sum(nCount_RNA)),by=annotation_reason];z<-melt(z,id.vars='annotation_reason');z[,fraction:=value/sum(value),by=variable];p<-ggplot(z,aes(reorder(annotation_reason,fraction),fraction,fill=variable))+geom_col(position='dodge')+coord_flip()+scale_y_continuous(labels=scales::percent)+jin_theme()+labs(x=NULL,y='Fraction of original Unknown',fill='Denominator');export(p,'original_reasons',10,4.5,8)
z<-d[,.(n=.N),by=.(diag_information_band,annotation_status)];z[,fraction:=n/sum(n),by=diag_information_band];z[,diag_information_band:=factor(diag_information_band,levels=c('<20','20–49','50–99','100–199','200–499','≥500'))];# ASCII fallback for actual stored bins
if(anyNA(z$diag_information_band)){z<-d[,.(n=.N),by=.(diag_information_band,annotation_status)];z[,fraction:=n/sum(n),by=diag_information_band];z[,diag_information_band:=factor(diag_information_band,levels=unique(d$diag_information_band[order(d$nFeature_RNA)]))]}
p<-ggplot(z,aes(diag_information_band,fraction,fill=annotation_status))+geom_col()+scale_fill_manual(values=stcol)+scale_y_continuous(labels=scales::percent)+jin_theme()+labs(x='nFeature band (descriptive only)',y='Object fraction',fill='Original status');export(p,'nFeature_strata',8,4.5,6.5)
z<-fread(file.path(out,'single_rule_ablation.tsv'));p<-ggplot(z,aes(reorder(removed_rule,original_unknown_get_label),original_unknown_get_label))+geom_col(fill='#80a2d3')+coord_flip()+jin_theme()+labs(x=NULL,y='Original Unknown getting a diagnostic label');export(p,'single_rule_ablation',9,4.5,9)
z<-fread(file.path(out,'label_crosstabs.tsv'));for(pair in list(c('Original_final','BLCA_pruned'),c('Original_final','HPCA_pruned'),c('BLCA_pruned','HPCA_pruned'))){zz<-z[from_method==pair[1]&to_method==pair[2]];p<-ggplot(zz,aes(to_label,from_label,fill=fraction_source))+geom_tile(color='white',linewidth=.4)+scale_fill_viridis_c(labels=scales::percent,name='Within row')+jin_theme()+theme(axis.text.x=element_text(angle=45,hjust=1))+labs(x=pair[2],y=pair[1]);export(p,paste0('cross_',pair[1],'_',pair[2]),8,5.8,6.5)}
mk<-fread(file.path(out,'candidate_marker_statistics.tsv'));genes<-c('KRT7','KRT19','UPK2','CD3D','TRAC','NKG7','LST1','LYZ','C1QA','COL1A1','DCN','LUM','PECAM1','VWF','TPSAB1','CPA3','MS4A1','CD79A','MZB1','JCHAIN','TNFRSF17','RGS5','MYH11','ACTG2');for(rtype in c('blca','hpca')){z<-mk[scope=='original_Unknown'&route==rtype&symbol%in%genes];z[,symbol:=factor(symbol,levels=genes)];z[,candidate:=factor(candidate,levels=rev(names(colors)))];p<-ggplot(z,aes(symbol,candidate,size=pct_positive*100,color=mean_log_normalized))+geom_point()+scale_size_area(max_size=5,limits=c(0,100),name='Positive (%)')+scale_color_viridis_c(name='Mean log-normalized',guide=guide_colorbar(display='rectangles'))+jin_theme()+theme(axis.text.x=element_text(angle=60,hjust=1))+labs(x=NULL,y='Original Unknown candidate');export(p,paste0('markers_unknown_',rtype),12,5.7,10)}
assets<-file.path(old,s,'spatial_assets');tr<-read_json(file.path(assets,'transform.json'),simplifyVector=TRUE);shape<-tr$model_image_shape_yx;scale<-tr$local_to_model_scale_xy;crop<-tr$fullres_crop_xyxy;mp<-tr$native_mpp;xx<-function(u)(crop[1]+(u+.5)/scale[1]-.5)*mp;yy<-function(u)-(crop[2]+(u+.5)/scale[2]-.5)*mp
bg<-readPNG(file.path(assets,'whole_HE.png'));cov<-readPNG(file.path(assets,'outside_supplied_bins.png'))
for(k in c('final_major','candidate_blca','candidate_hpca')){lev<-names(colors)[names(colors)%in%unique(d[[k]])];p<-ggplot(d,aes(nucleus_x_um,-nucleus_y_um))+annotation_raster(bg,xx(-.5),xx(shape[2]-.5),yy(shape[1]-.5),yy(-.5))+annotation_raster(cov,xx(-.5),xx(shape[2]-.5),yy(shape[1]-.5),yy(-.5))+geom_point_rast(aes(color=.data[[k]]),size=.12,raster.dpi=300)+scale_color_manual(values=colors,breaks=lev,name=if(k=='final_major')'Original' else 'Candidate')+guides(color=guide_legend(override.aes=list(size=3)))+coord_fixed(xlim=c(xx(-.5),xx(shape[2]-.5)),ylim=c(yy(shape[1]-.5),yy(-.5)),expand=FALSE)+jin_theme()+labs(x='Original x (um)',y='- Original y (um)');export(p,paste0('spatial_',k),8,6.5,6.5)}
# Four original ROI per section, faceted identical coordinates compare original and both candidates.
rois<-fread(file.path(assets,'rois.tsv'));rois<-rois[roi%in%c('stroma','small_nuclei','edge','far_UMI_hotspot')];stats<-list()
for(i in seq_len(nrow(rois))){b<-rois[i];z<-d[nucleus_x_um>=xx(b$x)&nucleus_x_um<xx(b$X)&-nucleus_y_um<=yy(b$y)&-nucleus_y_um>yy(b$Y)];im<-readPNG(file.path(assets,paste0(b$roi,'_HE.png')));bd<-readPNG(file.path(assets,paste0(b$roi,'_boundaries.png')));long<-melt(z,id.vars=c('cell_id','nucleus_x_um','nucleus_y_um'),measure.vars=c('final_major','candidate_blca','candidate_hpca'),variable.name='method',value.name='label');long[,method:=factor(method,levels=c('final_major','candidate_blca','candidate_hpca'),labels=c('Original','SingleR BLCA','SingleR HPCA'))];lev<-names(colors)[names(colors)%in%unique(long$label)];p<-ggplot(long,aes(nucleus_x_um,-nucleus_y_um))+annotation_raster(im,xx(b$x-.5),xx(b$X-.5),yy(b$Y-.5),yy(b$y-.5))+annotation_raster(bd,xx(b$x-.5),xx(b$X-.5),yy(b$Y-.5),yy(b$y-.5))+geom_point(aes(fill=label),shape=21,color='black',stroke=.35,size=1.5)+facet_wrap(~method,nrow=1)+scale_x_continuous(n.breaks=3)+scale_fill_manual(values=colors,breaks=lev,name='Label / candidate')+coord_fixed(xlim=c(xx(b$x-.5),xx(b$X-.5)),ylim=c(yy(b$Y-.5),yy(b$y-.5)),expand=FALSE)+jin_theme()+labs(x='Original x (um)',y='- Original y (um)');p<-p+theme(panel.spacing.x=grid::unit(.22,'in'));export(p,paste0('ROI_',b$roi),14,5.3,12.5)
 u<-z$final_major=='Unknown';stats[[i]]<-data.table(roi=b$roi,n=nrow(z),original_unknown=sum(u),unknown_agree=sum(u&z$diag_candidate_pattern=='both_nonpruned_agree'),unknown_disagree=sum(u&z$diag_candidate_pattern=='both_nonpruned_disagree'),unknown_BLCA_only=sum(u&z$diag_candidate_pattern=='BLCA_only_nonpruned'))}
fwrite(rbindlist(stats),file.path(out,'roi_comparison.tsv'),sep='\t');cat('PLOTS_COMPLETE',s,'\n')
